"use strict";

const daemon = require("daemon");
const exec = require("child_process").exec;
const fs = require("fs");

// COMMON

const common = require("./apply_common");
const syslog = common.syslog();

function updateBodyBoards(callback) {
    exec("/usr/local/bin/jibo-bbfw-update", function(error, stdout, stderr) {
        syslog.info(stdout);
        if (error) {
            common.fail(error);
        } else {
            callback();
        }
    });
}

function doServiceInstall(to_version) {
    syslog.info("Begin service update.");
    let extract_dir = common.extractDir(to_version, "services");
    const dev = fs.realpathSync("/dev/disk/by-partlabel/services");
    common.applyUpdate(extract_dir, dev, "/usr/local", function() {
        syslog.info("Update bodyboard firmware.");
        updateBodyBoards(function() {
            common.cleanScratchDir(extract_dir, function() {
                syslog.info("Services install completed!");
                common.finalizeInstall();
            });
        });
    });
}

function initServiceUpdate(to_version, tarball) {
    syslog.info("Initialize service update");
    common.writeWorkState("init", function() {
        let extract_dir = common.extractDir(to_version, "services");
        common.unpackUpdate(extract_dir, tarball, function(extract_dir) {
            doServiceInstall(to_version);
        });
    });
}

function retryServiceUpdate(from_version, filter) {
    syslog.info("Retry services update from %s", from_version);
    common.waitForWifiLink(120, function(error) {
        if (error) {
            common.fail(error);
        } else {
            common.getAvailableUpdate("services", from_version, filter,
                function(update, tarball) {
                    initServiceUpdate(update.toVersion, tarball);
                });
        }
    });
}

function executeStep(step, work_state, gui) {
    const ws = work_state.current();
    const bbfw_time_est = 90.0;
    const apply_time_est = common.bunzip2Estimate(ws.size) + bbfw_time_est;
    const retry_time_est = 30.0 + (2.0 * apply_time_est);
    const times = common.timeToPct([apply_time_est]);
    const apply_max_pct = times[0];
    const first_background = __dirname + "/Installer3.png";
    const second_background = __dirname + "/Installer3a.png";
    if (step == "retry") {
        gui.setBackground(second_background);
        gui.setPercent(0);
        gui.incrementTo(1.0, retry_time_est);
        retryServiceUpdate(ws.from, ws.filter);
    } else {
        gui.setBackground(first_background);
        gui.setPercent(0);
        gui.incrementTo(apply_max_pct, apply_time_est);
        initServiceUpdate(ws.to, ws.source);
    }
}

module.exports = {
    handlesSubsystem: function(subsystem) {
        return subsystem == "services";
    },
    execute: executeStep
}
